constexpr bool msgTypesUnique()
{
    for (size_t i = 0; i < kAllMsgTypes.size(); ++i) {
        for (size_t j = i + 1; j < kAllMsgTypes.size(); ++j) {
            if (kAllMsgTypes[i] == kAllMsgTypes[j]) {
                return false;
            }
        }
    }
    return true;
}

/// True if no registry entry lies in the `count` channels from `first`.
constexpr bool channelsClear(uint8_t first, size_t count)
{
    for (const uint8_t type : kAllMsgTypes) {
        if (type >= first && type < first + count) {
            return false;
        }
    }
    return true;
}

